export const signupTemplate = "<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Verify your KPM Workspace</title>\n  <!-- Import Geist from Google Fonts -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    /* Global font declarations */\n    body, table, td, h1, h2, p, a {\n      font-family: 'Geist', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol';\n    }\n  </style>\n</head>\n<body style=\"margin: 0; padding: 0; background-color: #f3f4f6;\">\n  <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"background-color: #f3f4f6; padding: 40px 0;\">\n    <tr>\n      <td align=\"center\">\n        <!-- Main Email Container -->\n        <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"max-width: 600px; background-color: #ffffff; border-radius: 8px; box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05); overflow: hidden; border: 1px solid #e5e7eb;\">\n          \n          <!-- Header Area -->\n          <tr>\n            <td align=\"center\" style=\"padding: 40px 0 20px 0;\">\n              <!-- Using KPM Primary Brand Color: #097255 -->\n              <h1 style=\"margin: 0; font-size: 32px; color: #097255; font-weight: 700; letter-spacing: -0.5px;\">\n                KPM\n              </h1>\n              <p style=\"margin: 5px 0 0 0; font-size: 13px; color: #6b7280; font-weight: 500; text-transform: uppercase; letter-spacing: 1px;\">\n                Kapuletu Project Manager\n              </p>\n            </td>\n          </tr>\n          \n          <!-- Body Content Area -->\n          <tr>\n            <td style=\"padding: 20px 40px 40px 40px;\">\n              <h2 style=\"margin: 0 0 20px 0; font-size: 20px; color: #171717; font-weight: 600;\">Secure Your Workspace</h2>\n              \n              <!-- Dynamic Greeting -->\n              <p style=\"margin: 0 0 24px 0; font-size: 16px; line-height: 24px; color: #171717;\">\n                Hello {{ .Data.full_name }},\n              </p>\n              \n              <p style=\"margin: 0 0 24px 0; font-size: 16px; line-height: 24px; color: #171717;\">\n                Thank you for choosing KPM. As an Organization Admin, you are one step away from unlocking your enterprise workspace. Once your email is verified, you will be able to configure global standards, provision projects, and securely invite your Project Managers and Team Members.\n              </p>\n\n              <p style=\"margin: 0 0 32px 0; font-size: 16px; line-height: 24px; color: #171717;\">\n                Please authenticate your account by clicking the secure button below.\n              </p>\n              \n              <!-- Call to Action Button -->\n              <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"margin-bottom: 32px;\">\n                <tr>\n                  <td align=\"center\">\n                    <!-- Button uses KPM Primary color #097255 -->\n                    <a href=\"{{ .ConfirmationURL }}\" style=\"display: inline-block; background-color: #097255; color: #ffffff; text-decoration: none; font-size: 15px; font-weight: 600; padding: 14px 32px; border-radius: 6px; text-align: center;\">\n                      Verify Email &amp; Initialize Workspace\n                    </a>\n                  </td>\n                </tr>\n              </table>\n              \n              <!-- Fallback Link Section -->\n              <p style=\"margin: 0 0 12px 0; font-size: 14px; line-height: 22px; color: #6b7280;\">\n                If the button above does not work, copy and paste this link securely into your web browser:\n              </p>\n              \n              <p style=\"margin: 0; font-size: 14px; line-height: 22px; word-break: break-all;\">\n                <!-- Link uses KPM Secondary/Info color -->\n                <a href=\"{{ .ConfirmationURL }}\" style=\"color: #1b4580; text-decoration: underline;\">\n                  {{ .ConfirmationURL }}\n                </a>\n              </p>\n            </td>\n          </tr>\n          \n          <!-- Footer Area -->\n          <tr>\n            <td style=\"padding: 30px 40px; background-color: #f3f4f6; border-top: 1px solid #e5e7eb; text-align: center;\">\n              <p style=\"margin: 0 0 8px 0; font-size: 13px; color: #6b7280; line-height: 1.5;\">\n                This is an automated security message from Kapuletu Project Manager.<br/>If you did not initiate this registration, please safely ignore this email.\n              </p>\n              <p style=\"margin: 0; font-size: 13px; color: #6b7280; font-weight: 500;\">\n                &copy; 2026 KPM. All rights reserved.\n              </p>\n            </td>\n          </tr>\n\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n";

